/**
 * 同一批形参判据换个**接收者写法**：`var rs: String = "abc"` 再 `rs.repeat("a")`。
 * `1106` 格的句子是 `tmp/probe-argtype/packed3.mts` 量到的引擎原文，与字面量接收者那一趟（`p2-t4.txt`）逐格比过、一格不差
 * （`cmp-typed.mts`：同 1358 / 不同 0），所以 `FACE_ARG_*` 那两张表对带标注的变量接收者照用。
 */
import { describe, expect, it } from "vitest";
import { analyze } from "@gds2js/compiler/lower/analyze";
import { lower } from "@gds2js/compiler/lower/lower";
import { parseSource } from "@gds2js/compiler/parse/parser";

const diags = async (src: string): Promise<string[]> => {
  const tree = await parseSource(`extends SceneTree\n\nfunc _initialize():\n\t${src}\n\tprint("X||", 1)\n\tquit()\n`);
  return analyze(lower(tree)).diagnostics.map((d) => d.message);
};

