describe("带类型标注的变量接收者走同一张形参表", () => {
  it.each(REFUSE)("拒 %s", async (src, messages) => {
    expect(await diags(src)).toEqual(messages.split(" || "));
  });

  it.each(ACCEPT)("收 %s", async (src) => {
    expect(await diags(src)).toEqual([]);
  });
});
